// N = replicas per key
// W = acks required before a write is confirmed
// R = replicas consulted on a read
//
//   R + W > N  ⟹  read set ∩ write set ≠ ∅  ⟹  strong consistency
//
// N=3, W=2, R=2 → 4 > 3 ✓  and survives one node down on either path
const N = 3, W = 2, R = 2;

function replicasFor(key) {
  return ring.preferenceList(key, N);   // N distinct physical nodes
}

// The node the client happened to reach becomes the coordinator.
// No leader election, no failover — that's the Dynamo-style trade.

async function put(key, value) {
  const version = { node: SELF, counter: Date.now() };
  const writes = replicasFor(key).map((n) => n.put(key, value, version));

  let ok = 0;
  await new Promise((resolve, reject) => {
    writes.forEach((p) => p.then(
      () => { if (++ok === W) resolve(); },
      () => { if (writes.length - ok < W) reject(new Error('quorum lost')); },
    ));
  });

  return version;   // remaining replicas continue in the background
}

async function get(key) {
  const nodes = replicasFor(key);
  const replies = await anyOf(nodes.map((n) => n.get(key)), R);

  // quorum guarantees the newest is HERE; it doesn't tell you which
  let winner = replies[0];
  for (const r of replies) {
    if (descendsFrom(r.version, winner.version)) winner = r;
  }

  repairStale(key, winner, replies);   // background, off the read path
  return winner.value;
}

function repairStale(key, winner, replies) {
  for (const r of replies) {
    if (r.version !== winner.version) {
      r.node.put(key, winner.value, winner.version).catch(() => {});
    }
  }
}

// concurrent  → neither descends from the other → a REAL conflict
function descendsFrom(a, b) {
  return Object.keys(b).every((node) => (a[node] ?? 0) >= (b[node] ?? 0));
}

// Resolution is a POLICY choice, not a technical one:
//   last-write-wins → simple, silently loses an update, trusts clocks
//   return both     → the cart model: union the items
//   CRDT           → merge defined so concurrency always converges

await get('cart:42',      { R: 2 });  // must see the user's own write
await get('recs:42',      { R: 1 });  // stale suggestion is invisible
await put('inventory:99', { W: 3 });  // overselling costs real money

// W=1,R=1 → fastest, eventually consistent (2 ≯ 3)
// W=3     → strongly consistent reads at R=1, but ONE node down
//           blocks every write. Availability traded explicitly.
